        'rh.stress.insight.a':  '⚠️ A 30% crash in Year 1 turns a <strong>healthy corpus into depletion at age {n}</strong>. Your base case outlasts life expectancy — but a bad sequence erases that advantage. The 3-bucket strategy keeps 1–2 years of expenses in liquid assets so you never sell equity at the worst time.',
