        'epf.table.th.balance': 'Year-End Balance',
        'epf.pension.formula':  '({salary} × {yrs} yrs) ÷ 70',
        'epf.insight.html':     '<strong>💡 Insight:</strong> Your EPF is an <strong>automatic, compulsory, tax-free</strong> retirement fund. Employee + employer together contribute {total}/mo today (you: {emp} + employer EPF: {erEPF} + EPS pension: {eps}). At {rate}% compounded for {yrs} years, interest alone adds {interest} — <strong>{mult}x your total contributions</strong>. You\'ll also receive an EPS pension of ~{pension}/mo, calculated as ({pensionSalary} × {serviceYrs} yrs) ÷ 70. <span style="color:#b91c1c;"><strong>⚠ Tax reminder:</strong> Withdrawing before 5 years makes the entire amount taxable at your slab rate with 10% TDS (u/s 192A) if &gt;₹50K. After 5 years it is fully tax-free.</span>',
        'epf.eps.body':         '<div class="flex gap-1.5"><span class="text-amber-500 font-bold mt-0.5">▸</span><span>Of your employer\'s <strong>12% contribution</strong>, only <strong>₹1,250/mo</strong> (8.33% of ₹15,000 wage ceiling) goes to the <strong>EPS pension fund</strong> — the rest goes to your EPF balance.</span></div><div class="flex gap-1.5"><span class="text-amber-500 font-bold mt-0.5">▸</span><span><strong>Pension formula:</strong> Monthly Pension = (Pensionable Salary × Service Years) ÷ 70, where Pensionable Salary = min(Basic, ₹15,000) and max service counted is 35 years.</span></div><div class="flex gap-1.5"><span class="text-amber-500 font-bold mt-0.5">▸</span><span>Example: ₹15,000 × 30 years ÷ 70 = <strong>~₹6,428/mo pension</strong>. Pension is <em>not</em> tax-free — taxed at your slab rate after retirement.</span></div><div class="flex gap-1.5"><span class="text-amber-500 font-bold mt-0.5">▸</span><span>EPS contributions are <strong>not included</strong> in the EPF balance — they build a separate pension entitlement payable for life.</span></div>',
        'epf.rules.body':       '<div class="flex gap-1.5"><span class="text-red-400 font-black mt-0.5">✗</span><span><strong>Before 5 years of continuous service:</strong> Entire EPF withdrawal is <strong>taxable as per your income-tax slab</strong> in the year of withdrawal. TDS at <strong>10%</strong> (u/s 192A) if &gt;₹50K. No PAN? TDS jumps to <strong>30%</strong>.</span></div><div class="flex gap-1.5"><span class="text-green-600 font-black mt-0.5">✓</span><span><strong>After 5 years of continuous service:</strong> EPF withdrawal is <strong>fully tax-free</strong> (Sec 10(12)). No TDS, no income-tax liability.</span></div><div class="flex gap-1.5"><span class="text-amber-600 font-bold mt-0.5">▸</span><span><strong>Key decision:</strong> Switching jobs before 5 years? <em>Do not withdraw EPF</em> — transfer via EPFO portal (Form 13) to preserve tax exemption and compound interest.</span></div><div class="flex gap-1.5"><span class="text-amber-600 font-bold mt-0.5">▸</span><span>EPS (pension) withdrawal before 10 years gives a lump-sum; after 10 years you must opt for monthly pension or defer to 58.</span></div>',
        'howto.epfcalc.what':  'Project your EPF balance at retirement accounting for salary growth and the current 8.15% p.a. rate.',
