        'howto.ppfnps.step4':  '4. Compare maturity corpus, annuity income, and total tax deduction benefit',
        'howto.ppfnps.tip':    'NPS unlocks an extra ₹50,000 deduction under 80CCD(1B) — on top of the standard ₹1.5L 80C limit.',
        'howto.insure.what':   'Check whether your life and health cover is enough using the industry-standard HLV method.',
        'howto.insure.step1':  '1. Enter annual income, outstanding loans, and number of financial dependents',
