        'howto.insure.step4':  '4. Check Critical Illness, Disability, and Parents health coverage gaps too',
        'howto.insure.tip':    'Rule of thumb: life cover = 10–15× annual income; health = ₹10L base + ₹25L super top-up minimum.',
        'howto.mfexplorer.what':  'Browse 1,000+ mutual funds live with NAV, star ratings, rolling returns, and a built-in fund comparator.',
        'howto.mfexplorer.step1': '1. Pick a category using the Equity / Debt / Hybrid / Others dropdowns — or search by fund name or AMC',
