        'howto.mfkit.tip':    'पहली बार निवेश? इंडेक्स फंड (Nifty 50) या लार्ज-कैप फंड से शुरुआत करें — सरल, कम लागत, सिद्ध।',
        'howto.fundpicker.what':  'ऐल्फा, शार्प रेशियो, सॉर्टिनो रेशियो और व्यय अनुपात का उपयोग करके म्यूचुअल फंड का मूल्यांकन करना समझें।',
        'howto.fundpicker.step1': '1. किसी भी मेट्रिक कार्ड पर क्लिक करें — सरल भाषा में उदाहरण सहित व्याख्या देखें',
        'howto.fundpicker.step2': '2. प्रत्येक मेट्रिक के लिए "अच्छे" नंबर की पहचान करें',
        'howto.fundpicker.step3': '3. MF Explorer में फंड तुलना करते समय इन मेट्रिक्स को लागू करें',
        'howto.fundpicker.tip':   'इक्विटी फंड के लिए: शार्प > 1 अच्छा संकेत है। डेट फंड के लिए: व्यय अनुपात सबसे अधिक मायने रखता है।',
        'howto.coffeecan.what':  'ROCE, राजस्व वृद्धि, ऋण स्तर और खाई मानदंड का उपयोग करके दीर्घकालिक गुणवत्ता कंपाउंडर स्टॉक को स्क्रीन करें।',
        'howto.coffeecan.step1': '1. कंपनी सूची ब्राउज़ करें — प्रत्येक स्टॉक का ROCE, Rev CAGR, D/E और FCF स्कोर देखें',
        'howto.coffeecan.step2': '2. सेक्टर फिल्टर और सॉर्ट बटन का उपयोग करके पसंदीदा सेक्टर की कंपनियां खोजें',
        'howto.coffeecan.step3': '3. किसी भी कंपनी कार्ड पर "विवरण" टैप करें — योग्यता के कारण, जोखिम संकेत और खाई विश्लेषण देखें',
        'howto.coffeecan.tip':   'रॉबर्ट किर्बी की 1984 की रणनीति के नाम पर: उच्च-गुणवत्ता वाले व्यवसाय खरीदें, उन्हें Coffee Can में बंद करें, 10 वर्षों के लिए छोड़ दें।',
        'howto.hracalc.what':  'धारा 10(13A) के तहत HRA छूट की गणना करें और किराए पर वार्षिक कर बचत जानें।',
        'howto.hracalc.step1': '1. मूल वेतन, नियोक्ता से प्राप्त HRA और मासिक किराया दर्ज करें',
        'howto.hracalc.step2': '2. शहर का प्रकार चुनें: मेट्रो (बेसिक का 50%) या गैर-मेट्रो (40%)',
        'howto.hracalc.step3': '3. छूट प्राप्त HRA राशि और कुल वार्षिक कर बचत देखें',
        'howto.hracalc.tip':   'छूट = (वास्तविक HRA | किराया − बेसिक का 10% | बेसिक का 50%/40%) में से सबसे कम।',
