        /* How-to: Growth Calculator */
        'howto.growth.what':    'ఏ కాల వ్యవధిలోనైనా ఏకమొత్తం లేదా నెలవారీ SIP చక్రవడ్డీతో ఎలా పెరుగుతుందో అంచనా వేయండి.',
        'howto.growth.step1':   '1. పైన ఉన్న టాగుల్ ఉపయోగించి ఏకమొత్తం (ఒకసారి) లేదా SIP (నెలవారీ) ఎంచుకోండి',
        'howto.growth.step2':   '2. మొత్తం, ఆశించిన వార్షిక రిటర్న్ (%), మరియు కాల వ్యవధి (సంవత్సరాలు) నమోదు చేయండి',
        'howto.growth.step3':   '3. ద్రవ్యోల్బణ సర్దుబాటు టాగుల్ చేయండి — భవిష్యత్ కార్పస్ యొక్క నిజ కొనుగోలు శక్తి చూడండి',
        'howto.growth.step4':   '4. LTCG టాగుల్ చేయండి — ₹1.25L పైన లాభాలపై 12.5% ఈక్విటీ పన్ను తగ్గించండి',
        'howto.growth.tip':     'రిటర్న్ రేటు తెలియడం లేదా? Nifty 50 20 సంవత్సరాలలో సగటున ~12% ప్రతి సంవత్సరం ఇచ్చింది; FD 6–7% ఇస్తుంది.',
        /* How-to: Goal Planner */
        'howto.goal.what':      'నిర్దిష్ట ఆర్థిక లక్ష్యాన్ని చేరుకోవడానికి ఈరోజు అవసరమైన నెలవారీ SIP లేదా ఏకమొత్తాన్ని కనుగొనండి.',
        'howto.goal.step1':     '1. లక్ష్య రకాన్ని ఎంచుకోండి (విద్య, పెళ్ళి, ఇల్లు, పదవీవిరమణ…) లేదా మీ స్వంతంగా రాయండి',
        'howto.goal.step2':     '2. లక్ష్య కార్పస్ మొత్తం మరియు అవసరమయ్యే సంవత్సరాల సంఖ్య నమోదు చేయండి',
        'howto.goal.step3':     '3. ఆశించిన రిటర్న్ రేటు సెట్ చేయండి — కేటగిరీ ప్రీసెట్లు ఆ లక్ష్య రకానికి ద్రవ్యోల్బణాన్ని స్వయంచాలకంగా పూరిస్తాయి',
        'howto.goal.step4':     '4. అవసరమైన నెలవారీ SIP మరియు ఏకమొత్తం సమానాన్ని వెంటనే చూడండి',
        'howto.goal.tip':       'పిల్లల విద్య ప్రీసెట్ 10–12% ద్రవ్యోల్బణాన్ని అనుమానిస్తుంది. మీరు మార్చవచ్చు — ప్రైవేట్ కళాశాల ఖర్చులు విస్తృతంగా మారుతాయి.',

        'howto.homeloan.what':  'EMI కాల్క్యులేటర్, ముందస్తు చెల్లింపు ప్రయోజనం, అద్దె vs కొనుగోలు విశ్లేషణ, మరియు సెక్షన్ 24(b) పన్ను ఆదా — అన్నీ ఒకే సాధనంలో.',
        'howto.homeloan.step1': 'EMI ట్యాబ్: రుణ మొత్తం, వడ్డీ రేటు, మరియు కాల వ్యవధి నమోదు చేయండి — మీ ఖచ్చితమైన నెలవారీ EMI పొందండి',
        'howto.homeloan.step2': 'ముందస్తు చెల్లింపు ట్యాబ్: ఏకమొత్తం చెల్లింపు మొత్తం వడ్డీ మరియు కాల వ్యవధిని ఎలా తగ్గిస్తుందో చూడండి',
        'howto.homeloan.step3': 'అద్దె vs కొనుగోలు ట్యాబ్: మీ నగరంలో యాజమాన్యం vs అద్దె యొక్క నిజమైన 10/20 సంవత్సరాల వ్యయాన్ని పోల్చండి',
        'howto.homeloan.step4': 'పన్ను ఆదా ట్యాబ్: సెక్షన్ 24(b) కింద హోమ్ లోన్ వడ్డీపై వార్షిక తగ్గింపు లెక్కించండి',
        'howto.homeloan.tip':   'ఏదైనా సంతకం చేయడానికి ముందు అద్దె vs కొనుగోలు ట్యాబ్ చూడండి — 7 సంవత్సరాల కంటే తక్కువ కాల వ్యవధికి, అద్దె తరచుగా ఆర్థికంగా గెలుస్తుంది.',

        'howto.stepupsip.what':  'ఫ్లాట్ నెలవారీ SIP మరియు ప్రతి సంవత్సరం 10% పెరిగే SIP మధ్య నాటకీయ తేడాను చూడండి.',
        'howto.stepupsip.step1': '1. మీ ప్రారంభ నెలవారీ SIP మొత్తాన్ని నమోదు చేయండి',
        'howto.stepupsip.step2': '2. ఆశించిన వార్షిక రిటర్న్ రేటు మరియు పెట్టుబడి కాలం (సంవత్సరాలు) సెట్ చేయండి',
        'howto.stepupsip.step3': '3. ఫ్లాట్ SIP vs స్టెప్-అప్ SIP కార్పస్‌ని పక్కపక్కన పోల్చండి',
        'howto.stepupsip.tip':   '₹5,000 SIPని సంవత్సరానికి 10% పెంచడం ద్వారా 20 సంవత్సరాలలో ₹15,000 ఫ్లాట్ SIPని అధిగమించవచ్చు — చక్రవడ్డీ వ్యత్యాసం అద్భుతంగా ఉంటుంది.',

        'howto.retirementhub.what':  'మీ పూర్తి రిటైర్మెంట్ కార్పస్ (EPF + PPF + NPS + SIP) ప్రొజెక్ట్ చేసి, 25-30 సంవత్సరాలు నిలిచే పన్ను-సమర్థ ఉపసంహరణ ప్రణాళిక వేయండి.',
        'howto.retirementhub.step1': '1. ప్రస్తుత వయసు, లక్ష్య రిటైర్మెంట్ వయసు మరియు రిటైర్మెంట్‌లో అంచనా నెలవారీ ఖర్చులు నమోదు చేయండి',
        'howto.retirementhub.step2': '2. ప్రస్తుత EPF, PPF మరియు NPS బ్యాలెన్స్‌లతో పాటు నెలవారీ SIP జోడించండి',
        'howto.retirementhub.step3': '3. డ్రాడౌన్ ప్లానర్‌కి వెళ్ళండి: SWP ఉపసంహరణ మొత్తం సెట్ చేసి క్షీణత సమయరేఖ చూడండి',
        'howto.retirementhub.step4': '4. 3-బకెట్ వ్యూహంతో కార్పస్‌ను స్వల్పకాలిక, మధ్యకాలిక మరియు దీర్ఘకాలిక కేటాయింపులుగా విభజించండి',
        'howto.retirementhub.tip':   'మీ ఉపసంహరణ మొత్తంపై 6% ద్రవ్యోల్బణం ఎల్లప్పుడూ పరిగణించండి — నేడు ₹50K/నె ఖర్చు 20 సంవత్సరాలలో ₹1.6L అవుతుంది.',

