        'ulip.rec.strong_surrender': '🚨 <strong>సరెండర్ చేయమని దృఢంగా సిఫారసు.</strong> ఈ పాలసీ సేవింగ్స్ ఖాతా కంటే తక్కువ సంపాదిస్తుంది (%1 IRR). 7% FD కూడా మెరుగ్గా ఉంటుంది. BTID వ్యూహం <strong>%2</strong> అంచనా వేస్తుంది vs పాలసీ మెచ్యూరిటీ <strong>%3</strong>. <em>ముందుగా శుద్ధ టర్మ్ ప్లాన్ కొని, తర్వాత సరెండర్ చేయండి.</em>',
        'ulip.rec.likely_surrender': '⚠️ <strong>సరెండర్ చేయడం విలువైనది కావచ్చు.</strong> పాలసీ IRR %1 FD రేటుకు సమానంగా లేదా తక్కువగా ఉంది. BTID <strong>%2</strong> అంచనా vs <strong>%3</strong> — మిగులు <strong>%4</strong>. గమనిక: కొనసాగించడం వల్ల ~%5 మొత్తం 80C పన్ను ప్రయోజనం — దీన్ని పరిగణించండి. <em>సరెండర్ ముందు టర్మ్ బీమా కొనండి.</em>',
        'ulip.rec.consider_surrender': '💡 <strong>సరెండర్ పరిగణించండి.</strong> BTID ఎక్కువ సంపదను అంచనా వేస్తుంది. అయితే, %1 IRR FD రేటుకంటే ఎక్కువ. ముఖ్య ప్రశ్న: ఈ కవర్ (%2) మీ <em>ఏకైక</em> జీవిత బీమా ఏనా? అవుననే సమాధానమైతే, ముందుగా టర్మ్ ప్లాన్ కొనండి. ~%3 80C ప్రయోజనం మీ ప్రభావవంతమైన ఖర్చు తగ్గిస్తుంది.',
        'ulip.rec.continue': '✅ <strong>ఈ పరిస్థితిలో పాలసీ కొనసాగించండి.</strong> పాలసీ మెచ్యూరిటీ (%1) BTID అంచనాను మించింది. అయితే: <strong>ఎండోమెంట్ పాలసీపై ప్రాథమిక జీవిత కవరేజ్‌గా ఎప్పుడూ ఆధారపడవద్దు</strong> — ప్రత్యేక టర్మ్ ప్లాన్ కొనండి. పాలసీ బాండ్‌లో మెచ్యూరిటీ అంచనా వాస్తవికమైనదని కూడా ధృవీకరించండి.',
        'ulip.rec.marginal': '💡 <strong>సరిహద్దు కేసు.</strong> %1 IRR మరియు BTID ప్రయోజనం %2. నిర్ణయం మీ ఇతర 80C పెట్టుబడులు, రిస్క్ సామర్థ్యం మరియు ఇది మీ ఏకైక జీవిత కవరేజ్ ఏనా అనే దానిపై ఆధారపడుతుంది. నిర్ణయించే ముందు SEBI-నమోదు రుసుము-మాత్రమే సలహాదారుని సంప్రదించండి.',
        'coffeecan.title':                         '☕ కాఫీ క్యాన్',
