        'coffeecan.what.desc':               'రాబర్ట్ కిర్బీ (1984) చే సృష్టించబడి, భారతదేశంలో <strong>సౌరభ్ ముఖర్జీ (Marcellus Investment Managers)</strong> చే ప్రాచుర్యంలోకి వచ్చింది: అధిక-నాణ్యత వ్యాపారాలను "కాఫీ క్యాన్"లో పెట్టి 10 సంవత్సరాలు మర్చిపోండి. ప్రమాణాలు: <strong>≥10% రెవెన్యూ CAGR</strong>, <strong>≥15% ROCE</strong> దశాబ్దంలో, తక్కువ రుణం, సానుకూల ఫ్రీ క్యాష్ ఫ్లో, స్థిరమైన ప్రమోటర్ వాటా.',
