        /* How-to: Growth Calculator */
        'howto.growth.what':    'எந்த கால அளவிலும் மொத்த தொகை அல்லது மாதாந்திர SIP கூட்டு வட்டியில் எவ்வாறு வளருகிறது என்பதை கணக்கிடுங்கள்.',
        'howto.growth.step1':   '1. மேலே உள்ள மாற்றியைப் பயன்படுத்தி மொத்த தொகை (ஒரு முறை) அல்லது SIP (மாதாந்திர) தேர்ந்தெடுக்கவும்',
        'howto.growth.step2':   '2. தொகை, எதிர்பார்த்த வருடாந்திர வருவாய் (%), மற்றும் கால அளவு (ஆண்டுகள்) உள்ளிடவும்',
        'howto.growth.step3':   '3. பணவீக்க சரிசெய்தல் மாற்றவும் — எதிர்கால கார்பஸின் உண்மையான கொள்முதல் சக்தியை பாருங்கள்',
        'howto.growth.step4':   '4. LTCG மாற்றவும் — ₹1.25L மேல் ஆதாயத்திற்கு 12.5% ஈக்விட்டி வரி கழிக்கவும்',
        'howto.growth.tip':     'வருவாய் விகிதம் தெரியவில்லையா? Nifty 50 20 ஆண்டுகளில் சராசரியாக ~12% ஆண்டுக்கு கொடுத்துள்ளது; FD 6–7% கொடுக்கும்.',
        /* How-to: Goal Planner */
        'howto.goal.what':      'குறிப்பிட்ட நிதி இலக்கை அடைய இன்று தேவையான மாதாந்திர SIP அல்லது மொத்த தொகையை கண்டுபிடிக்கவும்.',
        'howto.goal.step1':     '1. இலக்கு வகையை தேர்ந்தெடுக்கவும் (கல்வி, திருமணம், வீடு, ஓய்வூதியம்…) அல்லது உங்களது இலக்கை எழுதவும்',
        'howto.goal.step2':     '2. இலக்கு தொகை மற்றும் எத்தனை ஆண்டுகளில் தேவை என்பதை உள்ளிடவும்',
        'howto.goal.step3':     '3. எதிர்பார்த்த வருவாய் விகிதம் அமைக்கவும் — வகை முன்னமைவுகள் அந்த இலக்கு வகைக்கு பணவீக்கத்தை தானாக நிரப்பும்',
        'howto.goal.step4':     '4. தேவையான மாதாந்திர SIP மற்றும் மொத்த தொகை சமகாரியை உடனடியாக பாருங்கள்',
        'howto.goal.tip':       'குழந்தை கல்வி முன்னமைவு 10–12% பணவீக்கத்தை கருதுகிறது. நீங்கள் மாற்றலாம் — தனியார் கல்லூரி செலவுகள் பரவலாக மாறுகின்றன.',

        'howto.homeloan.what':  'EMI கணிப்பான், முன்கூட்டிய கட்டணம் பயன், வாடகை vs வாங்குதல் பகுப்பாய்வு, மற்றும் பிரிவு 24(b) வரி சேமிப்பு — அனைத்தும் ஒரே கருவியில்.',
        'howto.homeloan.step1': 'EMI தாவல்: கடன் தொகை, வட்டி விகிதம், மற்றும் கால அளவு உள்ளிடவும் — உங்கள் சரியான மாதாந்திர EMI பெறுங்கள்',
        'howto.homeloan.step2': 'முன்கூட்டிய கட்டணம் தாவல்: ஒரு முறை தொகை கட்டணம் மொத்த வட்டி மற்றும் கால அளவை எவ்வாறு குறைக்கிறது என்று பாருங்கள்',
        'howto.homeloan.step3': 'வாடகை vs வாங்குதல் தாவல்: உங்கள் நகரில் உரிமை vs வாடகை 10/20 ஆண்டு செலவை ஒப்பிடுங்கள்',
        'howto.homeloan.step4': 'வரி சேமிப்பு தாவல்: பிரிவு 24(b) கீழ் வீட்டு கடன் வட்டியில் வருடாந்திர கழிவு கணக்கிடுங்கள்',
        'howto.homeloan.tip':   'எதுவும் கையொப்பமிடுவதற்கு முன் வாடகை vs வாங்குதல் தாவலைப் பாருங்கள் — 7 ஆண்டுகளுக்கும் குறைவான கால அளவில், வாடகை பெரும்பாலும் நிதி ரீதியாக வெல்கிறது.',

        'howto.stepupsip.what':  'ஒரே மாதாந்திர SIP மற்றும் ஒவ்வொரு ஆண்டும் 10% அதிகரிக்கும் SIP இடையேயான நாடகீய வித்தியாசத்தைப் பாருங்கள்.',
        'howto.stepupsip.step1': '1. உங்கள் தொடக்க மாதாந்திர SIP தொகையை உள்ளிடவும்',
        'howto.stepupsip.step2': '2. எதிர்பார்த்த வருடாந்திர வருவாய் விகிதம் மற்றும் முதலீட்டு கால அளவு (ஆண்டுகள்) அமைக்கவும்',
        'howto.stepupsip.step3': '3. ஃப்ளாட் SIP vs படி-உயர் SIP கார்பஸை பக்கத்தில் பக்கமாக ஒப்பிடுங்கள்',
        'howto.stepupsip.tip':   '₹5,000 SIPஐ ஆண்டுக்கு 10% அதிகரிப்பதன் மூலம் 20 ஆண்டுகளில் ₹15,000 ஃப்ளாட் SIPஐ வெல்லலாம் — கூட்டு வட்டி இடைவெளி வியக்கத்தக்கது.',

        'howto.retirementhub.what':  'உங்கள் முழு ஓய்வூதிய நிதியை (EPF + PPF + NPS + SIP) கணக்கிட்டு, 25-30 ஆண்டுகள் நீடிக்கும் வரி-திறன் திரும்பப்பெறல் திட்டத்தை வரையுங்கள்.',
        'howto.retirementhub.step1': '1. தற்போதைய வயது, இலக்கு ஓய்வு வயது மற்றும் ஓய்வில் எதிர்பார்க்கப்படும் மாதாந்திர செலவுகளை உள்ளிடவும்',
        'howto.retirementhub.step2': '2. தற்போதைய EPF, PPF மற்றும் NPS இருப்புகளுடன் மாதாந்திர SIP சேர்க்கவும்',
        'howto.retirementhub.step3': '3. டிராடவுன் திட்டமிடலுக்கு செல்லவும்: SWP திரும்பப்பெறல் தொகை அமைத்து குறைதல் காலக்கோட்டைப் பாருங்கள்',
        'howto.retirementhub.step4': '4. 3-வாளி உத்தியைப் பயன்படுத்தி நிதியை குறுகிய, நடுத்தர மற்றும் நீண்ட கால ஒதுக்கீடுகளாக பிரிக்கவும்',
