        'nps.insight.old.html': '<strong>💡 NPS நுண்ணறிவு:</strong> ₹{monthly}/மாதம் {years} ஆண்டுகள் {rate}% வட்டியில் <strong>{corpus}</strong> கார்பஸ் உருவாகும். <strong>{lumpsum} வரி இல்லாமல்</strong> ஒட்டுமொத்தமாகவும் <strong>{pension}</strong> மாதாந்திர ஓய்வூதியமும் கிடைக்கும். வாழ்க்கையில் மொத்த வரி சேமிப்பு: <strong>{taxsaved}</strong> (80C ₹{s80c} + 80CCD(1B) ₹{sccd} × {slab}% அடுக்கு). <span style="color:#b45309;"><strong>⚠ நினைவில் கொள்ளுங்கள்:</strong> மாதாந்திர வருடாந்திர ஓய்வூதியம் உங்கள் அடுக்கு வரி விகிதத்தில் வரிக்கு உட்படும்.</span>',
