        'coffeecan.disclaimer':                    '⚠ மறுப்பு',
        'coffeecan.header.sub':              'தரமான கம்பவுண்டர்கள் · 10+ ஆண்டுகள் வாங்கி வைத்திருங்கள் · சௌரப் முகர்ஜி / Marcellus கட்டமைப்பின் அடிப்படையில்',
        'coffeecan.what.desc':               'ராபர்ட் கிர்பி (1984) உருவாக்கி, இந்தியாவில் <strong>சௌரப் முகர்ஜி (Marcellus Investment Managers)</strong> பிரபலப்படுத்தினார்: தரமான வணிகங்களை "காபி கேன்"னில் வைத்து 10 ஆண்டுகள் மறந்துவிடுங்கள். அளவுகோல்கள்: <strong>≥10% வருவாய் CAGR</strong>, <strong>≥15% ROCE</strong> ஒரு தசாப்தத்தில், குறைந்த கடன், நேர்மறை இலவச பணப்புழக்கம், நிலையான பதவிதாரர் பங்கு.',
