                directvsregular:'ప్రతి ఫండ్ రెండు ప్లాన్లు ఇస్తుంది: డైరెక్ట్ (AMC నుండి నేరుగా) మరియు రెగ్యులర్ (బ్రోకర్ ద్వారా). ఫండ్, మేనేజర్, వ్యూహం 100% ఒకటే — కేవలం వ్యయ నిష్పత్తి వేరు.',
