    function setSplashLang(lang) {
        // Update both the splash buttons and the nav buttons
        _lang = lang;
        try { localStorage.setItem('aw_lang', lang); } catch(e) {}
        ['en','hi','te','ta'].forEach(function(l) {
            var sb = document.getElementById('slt-' + l);
            if (sb) sb.classList.toggle('splash-lang-active', l === lang);
            var nb = document.getElementById('lt-' + l);
            if (nb) nb.classList.toggle('lang-btn-active', l === lang);
        });
        // applyLang() works on all data-i18n elements including splash
        applyLang();
    }

    function setLang(lang) {
        _lang = lang;
        try { localStorage.setItem('aw_lang', lang); } catch(e) {}
        ['en','hi','te','ta'].forEach(function(l) {
            var b = document.getElementById('lt-' + l);
            if (b) b.classList.toggle('lang-btn-active', l === lang);
            var sb = document.getElementById('slt-' + l);
            if (sb) sb.classList.toggle('splash-lang-active', l === lang);
        });
        applyLang();
    }

    function applyLang() {
        /* 1. Translate all static data-i18n elements */
        document.querySelectorAll('[data-i18n]').forEach(function(el) {
            var key = el.getAttribute('data-i18n');
            var val = _t(key);
            if (val && val !== key) el.textContent = val;
        });
        /* 1b. Translate elements with HTML content (data-i18n-html) */
        document.querySelectorAll('[data-i18n-html]').forEach(function(el) {
            var key = el.getAttribute('data-i18n-html');
            var val = _t(key);
            if (val && val !== key) el.innerHTML = val;
        });

        /* 2. Patch "New Regime" dropdown option labels with current FY year */
        ['tx-regime','nps-regime','ctc-regime','grat-regime','gc-regime'].forEach(function(id) {
            var sel = document.getElementById(id);
            if (sel && sel.options[0]) {
                sel.options[0].text = 'New Regime (' + _fyStr + ')';
            }
        });

        /* 3. WhatsApp share buttons (contain SVG child) */
        var waLabel = _lang === 'hi' ? 'WhatsApp पर शेयर करें'
                    : _lang === 'te' ? 'WhatsApp లో షేర్ చేయండి'
                    : _lang === 'ta' ? 'WhatsApp இல் பகிர்'
                    : 'Share on WhatsApp';
        document.querySelectorAll('.wa-share-btn').forEach(function(btn) {
            var svg = btn.querySelector('svg');
            if (!svg) return;
            btn.innerHTML = '';
            btn.appendChild(svg);
            btn.appendChild(document.createTextNode(' ' + waLabel));
        });

        /* 3. Health Score — re-translate live grade if already scored */
        var gradeEl = document.getElementById('hs-grade-title');
        if (gradeEl && gradeEl.dataset.gradeKey) {
            gradeEl.textContent = _t('hs.grade.' + gradeEl.dataset.gradeKey);
            var descEl = document.getElementById('hs-grade-desc');
            if (descEl) descEl.textContent = _t('hs.desc.' + gradeEl.dataset.gradeKey);
            var badgeEl = document.getElementById('hs-grade-badge');
            if (badgeEl) badgeEl.textContent = _t('hs.grade.' + gradeEl.dataset.gradeKey);
        }
        /* 4. "Not scored yet" badge */
        var badge = document.getElementById('hs-grade-badge');
        if (badge && (!badge.textContent.trim() || badge.textContent === _T.en['hs.notscored'] ||
            badge.textContent === _T.hi['hs.notscored'] || badge.textContent === _T.te['hs.notscored'] ||
            badge.textContent === _T.ta['hs.notscored'])) {
            badge.textContent = _t('hs.notscored');
        }

        /* 5. My Profile — re-apply dynamic strings that live outside data-i18n */
        if (typeof upRefreshRiskDisplay === 'function') upRefreshRiskDisplay();
        if (typeof upUpdateSummary      === 'function') upUpdateSummary();
        // Re-render risk quiz if it is currently visible
        var _upQuiz = document.getElementById('up-risk-quiz');
        if (_upQuiz && !_upQuiz.classList.contains('hidden') && typeof upRiskRender === 'function') upRiskRender();

        /* 1c. Translate placeholder attributes */
        document.querySelectorAll('[data-i18n-placeholder]').forEach(function(el) {
            var key = el.getAttribute('data-i18n-placeholder');
            var val = _t(key);
            if (val && val !== key) el.placeholder = val;
        });

        /* Reset MF Kit and Fund Picker so they re-render with new language */
        if (typeof _mfRendered !== 'undefined') {
            _mfRendered = false;
            _pickerRendered = false;
            var _mfGrid = document.getElementById('mf-tiles-grid');
            if (_mfGrid && _mfGrid.children.length > 0) {
                renderMFKit();
            }
            var _pkGrid = document.getElementById('picker-metric-cards');
            if (_pkGrid && _pkGrid.children.length > 0) {
                renderFundPickerPage();
            }
        }

        /* Re-render dynamic content for whichever tool is currently visible */
        var _cm = typeof window._currentMode !== 'undefined' ? window._currentMode : '';
        if (_cm === 'growth' || _cm === 'goal' || _cm === 'inflation') {
            if (typeof calculate === 'function') try { calculate(); } catch(e) {}
        }
        if (_cm === 'emergency') {
            if (typeof calcEmergency === 'function') try { calcEmergency(); } catch(e) {}
        }
        if (_cm === 'retirementhub') {
            if (typeof retHubCalc === 'function') try { retHubCalc(); } catch(e) {}
            if (typeof drawdownCalc === 'function') try { drawdownCalc(); } catch(e) {}
        }
        if (_cm === 'finplan') {
            if (typeof fpRenderExistingAmounts === 'function') try { fpRenderExistingAmounts(); } catch(e) {}
            if (typeof fpInitQuestions === 'function') try { fpInitQuestions(); } catch(e) {}
        }
        if (_cm === 'insure') {
            if (typeof insureCalc === 'function') try { insureCalc(); } catch(e) {}
        }
        if (_cm === 'ppfnps') {
            if (typeof ppfCalc === 'function') try { ppfCalc(); } catch(e) {}
            if (typeof npsCalc === 'function') try { npsCalc(); } catch(e) {}
        }
        if (_cm === 'ctcoptimizer') {
            if (typeof ctcCalc === 'function') try { ctcCalc(); } catch(e) {}
        }
        if (_cm === 'gratuity') {
            if (typeof gratCalc === 'function') try { gratCalc(); } catch(e) {}
        }
        if (_cm === 'debtplan') {
            if (typeof debtCalc === 'function') try { debtCalc(); } catch(e) {}
        }
        if (_cm === 'jointplan') {
            if (typeof jointPlanCalc === 'function') try { jointPlanCalc(); } catch(e) {}
        }
        if (_cm === 'cibil') {
            if (typeof cibilCalc === 'function') try { cibilCalc(); } catch(e) {}
        }
        if (_cm === 'fincal') {
            if (typeof finCalRender === 'function') try { finCalRender(); } catch(e) {}
        }
        if (_cm === 'selfempl') {
            if (typeof seCalcTax === 'function') try { seCalcTax(); } catch(e) {}
        }
        if (_cm === 'fixedincome') {
            if (typeof fiCalcFD === 'function') try { fiCalcFD(); } catch(e) {}
        }
        if (_cm === 'goldcomp') {
            if (typeof goldCalc === 'function') try { goldCalc(); } catch(e) {}
        }
        if (_cm === 'networth') {
            if (typeof nwCalc === 'function') try { nwCalc(); } catch(e) {}
        }
        if (_cm === 'ulipcheck') {
            if (typeof ucCalc === 'function') try { ucCalc(); } catch(e) {}
        }
        if (_cm === 'epfcalc') {
            if (typeof epfCalc === 'function') try { epfCalc(); } catch(e) {}
        }
        if (_cm === 'ssaplanner') {
            if (typeof ssaCalc === 'function') try { ssaCalc(); } catch(e) {}
        }
        if (_cm === 'stepupsip') {
            if (typeof suApplyLang === 'function') try { suApplyLang(); } catch(e) {}
        }
        if (_cm === 'coffeecan') {
            if (typeof coffeeCanRender === 'function') try { coffeeCanRender(); } catch(e) {}
        }
        if (_cm === 'dashboard' || _cm === 'dashcat-calc' || _cm === 'dashcat-mf' || _cm === 'dashcat-tax' || _cm === 'dashcat-fav' || _cm === 'dashcat-situation') {
            if (typeof dashRefreshHome === 'function') try { dashRefreshHome(); } catch(e) {}
        }
        if (_cm === 'growth' || _cm === 'goal' || _cm === 'inflation') {
            if (typeof growthApplyLang === 'function') try { growthApplyLang(); } catch(e) {}
        }
        if (_cm === 'homeloan') {
            if (typeof hlApplyLang === 'function') try { hlApplyLang(); } catch(e) {}
        }
        if (_cm && typeof injectHowToUse === 'function') {
            try { injectHowToUse(_cm); } catch(e) {}
        }
    }

    /* ── HS grade key map (English grade → short key) ─────── */
    var _HS_GRADE_KEYS = {
        'Financial Rockstar 🤘': 'rockstar',
        'Wealth Builder':        'builder',
        'On the Right Track':    'track',
        'Getting There':         'getting',
        'Wake-Up Call':          'wakeup',
        'SOS Mode':              'sos',
        'Financial Emergency':   'emergency'
    };

    /* ── HS category key map (English name → short key) ──── */
    var _HS_CAT_KEYS = {
        'Savings Rate':    'savings',
        'Debt Burden':     'debt',
        'Health Insurance':'health',
        'Term Insurance':  'term',
        'Emergency Fund':  'ef',
        'Spending Control':'spend',
        'Age Readiness':   'age'
    };

    /* ── Startup ─────────────────────────────────────────── */
    document.addEventListener('DOMContentLoaded', function() {
        try { _lang = localStorage.getItem('aw_lang') || 'en'; } catch(e) {}
        ['en','hi','te','ta'].forEach(function(l) {
            var b = document.getElementById('lt-' + l);
            if (b) b.classList.toggle('lang-btn-active', l === _lang);
            var sb = document.getElementById('slt-' + l);
            if (sb) sb.classList.toggle('splash-lang-active', l === _lang);
        });
        if (_lang !== 'en') applyLang();
    });